/// <summary>
/// Passed to the build(MXTXppRuntimeFormBuilder) method of an interpreted [RuntimeForm] class.
/// Adds data sources and controls to a form that exists only at runtime, and wires control
/// events to the interpreted class by name: a method ControlName_clicked, ControlName_modified,
/// ControlName_validate or ControlName_lookup is called with the control when that event fires.
/// form() and design() give the full native form build API for anything the helpers do not cover.
/// </summary>
public final class MXTXppRuntimeFormBuilder
{
    Form form;
    FormBuildDesign design;
    MXTXppRuntimeFormHost host;
    Map dataSources;
}

Method.Source:
internal static MXTXppRuntimeFormBuilder construct(Form _form, MXTXppRuntimeFormHost _host)
{
    MXTXppRuntimeFormBuilder builder = new MXTXppRuntimeFormBuilder();
    builder.init(_form, _host);
    return builder;
}

private void init(Form _form, MXTXppRuntimeFormHost _host)
{
    form = _form;
    host = _host;
    design = form.addDesign('Design');
    dataSources = new Map(Types::String, Types::Class);
}

public Form form()
{
    return form;
}

public FormBuildDesign design()
{
    return design;
}

public void caption(str _caption)
{
    design.caption(_caption);
}

private Object parent(Object _parent)
{
    return _parent ? _parent : design;
}

private boolean handles(str _controlName, str _event)
{
    return host.handles(_controlName + '_' + _event);
}

/// <summary>
/// Adds a data source on an installed table or view. Grids and fields bound to it show and edit
/// its rows with the standard form data handling.
/// </summary>
public FormBuildDataSource addDataSource(str _name, str _tableName)
{
    if (!tableName2Id(_tableName))
    {
        throw error(strFmt('Table %1 does not exist.', _tableName));
    }

    FormBuildDataSource dataSource = form.addDataSource(_name, _tableName);
    dataSource.table(tableName2Id(_tableName));
    dataSources.insert(_name, dataSource);
    return dataSource;
}

public FormBuildDataSource dataSource(str _name)
{
    if (!dataSources.exists(_name))
    {
        throw error(strFmt('Data source %1 has not been added.', _name));
    }

    return dataSources.lookup(_name);
}

public FormBuildGroupControl addGroup(str _name, str _caption = '', Object _parent = null)
{
    Object parent = this.parent(_parent);
    FormBuildGroupControl control = parent.addControl(FormControlType::Group, _name);
    if (_caption)
    {
        control.caption(_caption);
    }
    return control;
}

public FormBuildTabControl addTab(str _name, Object _parent = null)
{
    Object parent = this.parent(_parent);
    FormBuildTabControl control = parent.addControl(FormControlType::Tab, _name);
    return control;
}

public FormBuildTabPageControl addTabPage(FormBuildTabControl _tab, str _name, str _caption = '')
{
    FormBuildTabPageControl control = _tab.addControl(FormControlType::TabPage, _name);
    if (_caption)
    {
        control.caption(_caption);
    }
    return control;
}

public FormBuildStaticTextControl addStatic(str _name, str _text, Object _parent = null)
{
    Object parent = this.parent(_parent);
    FormBuildStaticTextControl control = parent.addControl(FormControlType::StaticText, _name);
    control.text(_text);
    return control;
}

public FormBuildButtonControl addButton(str _name, str _text, Object _parent = null)
{
    Object parent = this.parent(_parent);
    FormBuildButtonControl control = parent.addControl(FormControlType::Button, _name);
    control.text(_text);
    if (this.handles(_name, 'clicked'))
    {
        control.registerOverrideMethod(methodStr(FormButtonControl, clicked), methodStr(MXTXppRuntimeFormHost, buttonClicked), host);
    }
    return control;
}

public FormBuildStringControl addString(str _name, str _label = '', Object _parent = null)
{
    Object parent = this.parent(_parent);
    FormBuildStringControl control = parent.addControl(FormControlType::String, _name);
    control.label(_label ? _label : _name);
    if (this.handles(_name, 'modified'))
    {
        control.registerOverrideMethod(methodStr(FormStringControl, modified), methodStr(MXTXppRuntimeFormHost, stringModified), host);
    }
    if (this.handles(_name, 'validate'))
    {
        control.registerOverrideMethod(methodStr(FormStringControl, validate), methodStr(MXTXppRuntimeFormHost, stringValidate), host);
    }
    if (this.handles(_name, 'lookup'))
    {
        control.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(MXTXppRuntimeFormHost, stringLookup), host);
    }
    return control;
}

