/// <summary>
/// Adds a combo box over an installed base enum.
/// </summary>
public FormBuildComboBoxControl addComboBox(str _name, str _enumName, str _label = '', Object _parent = null)
{
    if (!enumName2Id(_enumName))
    {
        throw error(strFmt('Base enum %1 does not exist.', _enumName));
    }

    Object parent = this.parent(_parent);
    FormBuildComboBoxControl control = parent.addControl(FormControlType::ComboBox, _name);
    control.enumType(enumName2Id(_enumName));
    control.label(_label ? _label : _name);
    if (this.handles(_name, 'modified'))
    {
        control.registerOverrideMethod(methodStr(FormComboBoxControl, modified), methodStr(MXTXppRuntimeFormHost, comboBoxModified), host);
    }
    return control;
}

/// <summary>
/// Adds a grid over a data source added with addDataSource, with one column per field name.
/// </summary>
public FormBuildGridControl addGrid(str _name, str _dataSourceName, container _fieldNames = conNull(), Object _parent = null)
{
    FormBuildDataSource dataSource = this.dataSource(_dataSourceName);
    Object parent = this.parent(_parent);
    FormBuildGridControl grid = parent.addControl(FormControlType::Grid, _name);
    grid.dataSource(dataSource.id());

    for (int position = 1; position <= conLen(_fieldNames); position++)
    {
        this.addGridField(grid, _dataSourceName, conPeek(_fieldNames, position));
    }

    return grid;
}

public void addGridField(FormBuildGridControl _grid, str _dataSourceName, str _fieldName)
{
    FormBuildDataSource dataSource = this.dataSource(_dataSourceName);
    FieldId fieldId = fieldName2Id(dataSource.table(), _fieldName);
    if (!fieldId)
    {
        throw error(strFmt('Field %1 does not exist on data source %2.', _fieldName, _dataSourceName));
    }

    _grid.addDataField(dataSource.id(), fieldId);
}

/// <summary>
/// Adds a control bound to a field of a data source, typed and labelled from the field's metadata.
/// </summary>
public FormBuildControl addField(str _dataSourceName, str _fieldName, Object _parent = null)
{
    FormBuildDataSource dataSource = this.dataSource(_dataSourceName);
    FieldId fieldId = fieldName2Id(dataSource.table(), _fieldName);
    if (!fieldId)
    {
        throw error(strFmt('Field %1 does not exist on data source %2.', _fieldName, _dataSourceName));
    }

    Object parent = this.parent(_parent);
    return parent.addDataField(dataSource.id(), fieldId);
}
